'use strict';
const sE=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function sRequest(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options}),data=await r.json();if(!r.ok)throw Error(data.error||'Please try again.');return data;}
const sPost=(path,body={})=>sRequest(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});
if(document.body.dataset.simpleView==='models'){const form=document.querySelector('#simple-agency-filters'),city=document.querySelector('#simple-city'),field=document.querySelector('#simple-field'),status=document.querySelector('#simple-search-status'),results=document.querySelector('#simple-agency-results'),empty=document.querySelector('#simple-agency-empty');let matches=[];sRequest('/api/network/options').then(data=>{const defaults=['Bengaluru','Chennai','Delhi','Hyderabad','Kolkata','Mumbai','Pune'];city.innerHTML='<option value="">Choose a city</option>'+[...new Set([...defaults,...data.cities])].sort().map(c=>`<option>${sE(c)}</option>`).join('');}).catch(error=>{status.textContent=error.message;});form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button');button.disabled=true;status.textContent='Finding matching agencies…';try{const data=await sRequest('/api/network/search?city='+encodeURIComponent(city.value)+'&field='+encodeURIComponent(field.value));matches=data.agencies;status.textContent=`${matches.length} enrolled ${matches.length===1?'agency':'agencies'} in ${city.value} · ${field.value}`;empty.hidden=matches.length>0;results.innerHTML=matches.map(a=>`<article class="agency-card"><div class="agency-card-top"><span>ENROLLED WITH GLOSS</span><span>${sE(a.city)}</span></div><h3>${sE(a.name)}</h3><div class="agency-tags">${a.modeling_fields.split(',').map(f=>`<span>${sE(f)}</span>`).join('')}</div><p>${sE(a.description)}</p><button class="network-button" type="button" data-agency-info="${sE(a.id)}">Agency information ↗</button></article>`).join('');results.querySelectorAll('[data-agency-info]').forEach(b=>b.onclick=()=>{const a=matches.find(x=>x.id===b.dataset.agencyInfo);document.querySelector('#simple-agency-detail-content').innerHTML=`<p class="network-kicker">${sE(a.city)}</p><h2>${sE(a.name)}</h2><p>${sE(a.description)}</p><p><b>Modelling fields:</b> ${sE(a.modeling_fields)}</p><p>${a.freshers==='yes'?'Open to freshers':a.freshers==='no'?'Experienced talent focus':'Fresher acceptance: ask the agency'}</p><a class="network-button" href="${sE(a.application_url||a.website)}" target="_blank" rel="noopener noreferrer">Official ${a.application_url?'application page':'website'} ↗</a>`;document.querySelector('#simple-agency-details').showModal();});}catch(error){status.textContent=error.message;results.innerHTML='';empty.hidden=true;}finally{button.disabled=false;}};for(const select of [city,field])select.onchange=()=>{results.innerHTML='';empty.hidden=true;status.textContent='Choose both filters, then find agencies.';};document.querySelector('#close-agency-details').onclick=()=>document.querySelector('#simple-agency-details').close();}
if(document.body.dataset.simpleView==='dashboard'&&document.querySelector('#agency-account-status')){const status=document.querySelector('#agency-account-status'),content=document.querySelector('#agency-dashboard-content');let dashboard;const money=paise=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(paise/100);async function load(){try{dashboard=await sRequest('/api/network/agency-dashboard');document.querySelector('#agency-account-activate').hidden=dashboard.enrolled||!dashboard.approved;document.querySelector('#agency-account-missing').hidden=dashboard.enrolled||dashboard.approved;content.hidden=!dashboard.enrolled;status.textContent=dashboard.enrolled?'Your agency dashboard':dashboard.approved?'Approved agency account':'Agency enrolment required';if(!dashboard.enrolled)return;document.querySelector('#dashboard-agency-name').textContent=dashboard.name;document.querySelector('#dashboard-referral-code').textContent=dashboard.code;document.querySelector('#dashboard-referral-url').value=dashboard.url;document.querySelector('#copy-dashboard-referral').disabled=!dashboard.referralActive;document.querySelector('#dashboard-model-count').textContent=dashboard.models;document.querySelector('#dashboard-revenue-note').textContent=dashboard.purchasesTracked?'Verified qualifying paid GLOSS purchases':'Awaiting verified purchase tracking';document.querySelector('#dashboard-commission-note').textContent=dashboard.purchasesTracked?'2% of qualifying paid purchases':'Paid purchase tracking not connected';document.querySelector('#dashboard-revenue').textContent=dashboard.purchasesTracked?money(dashboard.revenuePaise):'—';document.querySelector('#dashboard-commission').textContent=dashboard.purchasesTracked?money(dashboard.commissionPaise):'—';document.querySelector('#dashboard-income-status').textContent=dashboard.purchasesTracked?'Commission reflects qualifying verified paid purchases. This is earned commission, not a payout confirmation.':'Model sign-ins are tracked. Paid purchase tracking is not connected yet, so revenue and commission are not available.';if(!dashboard.referralActive)document.querySelector('#dashboard-income-status').textContent+=' Your referral code is currently inactive.';}catch(error){status.textContent=error.message;}}document.querySelector('#activate-agency').onclick=async()=>{try{await sPost('/api/network/agency-enrol');await load();}catch(error){status.textContent=error.message;}};document.querySelector('#copy-dashboard-referral').onclick=async()=>{try{await navigator.clipboard.writeText(dashboard.url);document.querySelector('#dashboard-copy-status').textContent='Referral link copied.';}catch{document.querySelector('#dashboard-referral-url').select();document.querySelector('#dashboard-copy-status').textContent='Copy the selected link.';}};document.querySelector('#agency-enrol-request').onsubmit=async event=>{event.preventDefault();const form=event.target;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));data.message='Agency enrolment request for the referral dashboard.';data.consent=form.elements.consent.checked;const button=form.querySelector('button');button.disabled=true;try{await sPost('/api/network/interest',data);document.querySelector('#agency-enrol-status').textContent='Request received. GLOSS will review your agency enrolment.';form.reset();}catch(error){document.querySelector('#agency-enrol-status').textContent=error.message;}finally{button.disabled=false;}};load();}
